    "description": "",
    "signature": "export type NumberFieldAdmin = NumberLimitFieldAdmin & {\n  /** How the value is displayed in read-only Admin surfaces (list cells, read-only inputs). Does not affect storage or editing. */\n  format?: NumberFormat;\n};",
